            stateSum.pointsName = state.Points;
            stateSum.name = state.State;
            stateSum.Id = state.Id;
            stateSum.finalPoints = 600;
            if(stateSum.finalPoints<=sum)
            {
                countReachedStates++;
            }
            myStates.Add(stateSum);
        }

        if(countReachedStates>=States.Count)
        {
            DidIWin = true;
        }
        string lastAction = "";
        int actionNum = 1;
